content.solution_code:
class Weapon {
  constructor(name, damage) {
    this.name = name;
    this.damage = damage;
  }

  attack() {
    return `${this.name} attacks, dealing ${this.damage} damage.`;
  }
}

class Sword extends Weapon {
  constructor(name, damage, sharpness) {
    super(name, damage);
    this.sharpness = sharpness;
  }

  slash() {
    return `The ${this.name} slashes with ${this.sharpness} sharpness, dealing ${this.damage} damage!`;
  }
}

// Test cases (will be used by the game engine)
const broadsword = new Sword('Broadsword', 25, 'razor-sharp');
console.log(broadsword.attack());
console.log(broadsword.slash());

